package tree

import "fmt"

type Record struct {
	ID     int
	Parent int
	// feel free to add fields as you see fit
}

type Node struct {
	ID       int
	Children []*Node
	// feel free to add fields as you see fit
}

// Build reconstructs the tree from an unsorted set of records.
//
// Valid input satisfies:
//   - the IDs are exactly the set 0..len(records)-1 (no duplicates, no gaps),
//   - the root record (ID 0) has a parent ID equal to its own ID,
//   - every other record has a parent ID strictly lower than its own ID.
//
// Any violation (missing root, duplicate or non-continuous IDs, a root with a
// parent, or a cycle) results in an error. An empty input yields (nil, nil).
//
// The tree is built in O(n): records are indexed by ID, then walked in
// ascending ID order. Since every non-root parent has a lower ID, the parent
// node always exists when a child is linked, and children end up sorted by
// ID without an explicit sort.
func Build(records []Record) (*Node, error) {
	n := len(records)
	if n == 0 {
		return nil, nil
	}

	// Index records by ID, rejecting out-of-range and duplicate IDs.
	pos := make([]int, n)
	for i := range pos {
		pos[i] = -1
	}
	for i, r := range records {
		if r.ID < 0 || r.ID >= n {
			return nil, fmt.Errorf("record ID %d is out of range [0, %d)", r.ID, n)
		}
		if pos[r.ID] != -1 {
			return nil, fmt.Errorf("duplicate record with ID %d", r.ID)
		}
		pos[r.ID] = i
	}
	// By the pigeonhole principle the IDs are now exactly 0..n-1,
	// so the root (ID 0) exists and there are no gaps.

	// Validate parent relationships.
	for id, i := range pos {
		r := records[i]
		switch {
		case id == 0 && r.Parent != 0:
			return nil, fmt.Errorf("root record %d has parent %d", id, r.Parent)
		case id != 0 && (r.Parent < 0 || r.Parent >= id):
			return nil, fmt.Errorf("record %d has invalid parent %d", id, r.Parent)
		}
	}

	// Build the tree in ascending ID order.
	nodes := make([]*Node, n)
	for id, i := range pos {
		r := records[i]
		node := &Node{ID: id}
		nodes[id] = node
		if id != 0 {
			nodes[r.Parent].Children = append(nodes[r.Parent].Children, node)
		}
	}
	return nodes[0], nil
}
